#include <iostream>
#include <limits>

bool bajar_uno(int& valor) {
    const int minimo = std::numeric_limits<int>::lowest();
    // Esta version comprueba una condicion, pero todavia no cambia valor.
    return valor > minimo;
}

int main() {
    int distancia = 0;
    if (!(std::cin >> distancia) || distancia < 0 || distancia > 2) {
        return 1;
    }

    const int minimo = std::numeric_limits<int>::lowest();
    int valor = minimo + distancia;
    const int original = valor;
    const bool aceptado = bajar_uno(valor);

    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "EnMinimo=" << (valor == minimo) << '\n';
    std::cout << "Conservado=" << (valor == original) << '\n';

    return 0;
}

